CREATE TABLE "active_admin_comments" (id SERIAL PRIMARY KEY, "namespace" VARCHAR, "body" TEXT, "resource_id" VARCHAR NOT NULL, "resource_type" VARCHAR NOT NULL, "author_type" VARCHAR, "author_id" INTEGER, "created_at" TIMESTAMP NOT NULL, "updated_at" TIMESTAMP NOT NULL);
CREATE INDEX "index_active_admin_comments_on_author_type_and_author_id" ON "active_admin_comments" ("author_type", "author_id");
