CREATE INDEX "index_active_admin_comments_on_resource_type_and_resource_id" ON "active_admin_comments" ("resource_type", "resource_id");
CREATE TABLE "admin_users" (id SERIAL PRIMARY KEY, "email" VARCHAR DEFAULT '' NOT NULL, "encrypted_password" VARCHAR DEFAULT '' NOT NULL, "reset_password_token" VARCHAR, "reset_password_sent_at" TIMESTAMP, "remember_created_at" TIMESTAMP, "sign_in_count" INTEGER DEFAULT 0 NOT NULL, "current_sign_in_at" TIMESTAMP, "last_sign_in_at" TIMESTAMP, "current_sign_in_ip" INET, "last_sign_in_ip" INET, "created_at" TIMESTAMP NOT NULL, "updated_at" TIMESTAMP NOT NULL);
CREATE UNIQUE INDEX "index_admin_users_on_email" ON "admin_users" ("email");
