CREATE TABLE "elevations" (id SERIAL PRIMARY KEY, "long" NUMERIC, "latt" NUMERIC, "elevation" INTEGER, "created_at" TIMESTAMP NOT NULL, "updated_at" TIMESTAMP NOT NULL);
CREATE TABLE "hourly_weathers" (id SERIAL PRIMARY KEY, "date" TIMESTAMP, "temp" INTEGER, "description" VARCHAR, "shelter_id" INTEGER, "created_at" TIMESTAMP NOT NULL, "updated_at" TIMESTAMP NOT NULL, "wind" VARCHAR);
CREATE INDEX "index_hourly_weathers_on_shelter_id" ON "hourly_weathers" ("shelter_id");
CREATE TABLE "keys" (id SERIAL PRIMARY KEY, "key" VARCHAR, "created_at" TIMESTAMP NOT NULL, "updated_at" TIMESTAMP NOT NULL);
CREATE TABLE "shelters" (id SERIAL PRIMARY KEY, "name" VARCHAR, "mileage" NUMERIC, "elevation" INTEGER, "long" NUMERIC, "latt" NUMERIC, "state_id" INTEGER, "created_at" TIMESTAMP NOT NULL, "updated_at" TIMESTAMP NOT NULL);
CREATE INDEX "index_shelters_on_state_id" ON "shelters" ("state_id");
CREATE TABLE "states" (id SERIAL PRIMARY KEY, "name" VARCHAR, "abbreviation" VARCHAR, "created_at" TIMESTAMP NOT NULL, "updated_at" TIMESTAMP NOT NULL);
CREATE TABLE "weathers" (id SERIAL PRIMARY KEY, "weather_date" TIMESTAMP, "high" INTEGER, "low" INTEGER, "description" VARCHAR, "shelter_id" INTEGER, "created_at" TIMESTAMP NOT NULL, "updated_at" TIMESTAMP NOT NULL, "wind" VARCHAR);
CREATE INDEX "index_weathers_on_shelter_id" ON "weathers" ("shelter_id");
ALTER TABLE hourly_weathers ADD FOREIGN KEY (shelter_id) REFERENCES shelters(id);
ALTER TABLE shelters ADD FOREIGN KEY (state_id) REFERENCES states(id);
