INSERT INTO weathers(weather_date,high,low,description,shelter_id,wind,created_at,updated_at) SELECT CURRENT_DATE+d+INTERVAL '12 hours',50+s.id%15+(d%3)*2,32+s.id%15,(ARRAY['clear sky','scattered clouds','light rain'])[d%3+1],s.id,'6 mph SW',NOW(),NOW() FROM shelters s CROSS JOIN generate_series(0,6) d;
INSERT INTO hourly_weathers(date,temp,description,shelter_id,wind,created_at,updated_at) SELECT CURRENT_DATE+n*INTERVAL '3 hours',41+s.id%15+n%4,(ARRAY['clear sky','scattered clouds','light rain'])[n%3+1],s.id,'6 mph SW',NOW(),NOW() FROM shelters s CROSS JOIN generate_series(0,55) n;
